import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int s = Integer.parseInt(scanner.nextLine());

        int n = 0;
        while (true) {
            if (s >= 100) {
                s -= 100;
                n++;
            } else if (s >= 20) {
                s -= 20;
                n++;
            } else if (s >= 10) {
                s -= 10;
                n++;
            } else if (s >= 5) {
                s -= 5;
                n++;
            } else if (s >= 1) {
                s -= 1;
                n++;
            } else {
                System.out.println(n);
                break;
            }
        }
    }
}

